import{z as s,x as B,o as E,c as d,q as o,j as r,D as e,d as t,s as i,S as n,b as A}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"自适应 RAG","description":"","frontmatter":{"title":"自适应 RAG","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/adaptive-rag.md","filePath":"llm/adaptive-rag.md","lastUpdated":1791063341000}'),p={name:"llm/adaptive-rag.md"};function m(u,a,h,f,_,c){const l=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=o('<h1 id="自适应-rag" tabindex="-1">自适应 RAG <a class="header-anchor" href="#自适应-rag" aria-label="Permalink to &quot;自适应 RAG&quot;">​</a></h1><div class="epigraph"><p>不是每个问题都该检索。参数已会的短事实检索会引入噪声；需要证据的问题不检索会编造。路由本身要被评测。</p><footer>—— Jeong 等 Adaptive-RAG；检索触发与迭代深度当决策</footer></div><p><a href="/llm/rag-evaluation">上一课</a>给出能否定位故障段的指标。下一步是策略：何时检索、检索几次。Jeong 等人的 Adaptive-RAG 按问题复杂度选单跳、多跳或直答。缺口是把检索当<strong>可选动作</strong>，而不是管道常量。后课上下文压缩默认：已经决定检索之后，才谈塞进窗口之前怎么剪。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一律检索：延迟固定税、无关块污染、过时索引干扰已掌握的常识。一律不检索：私有知识与时效问答失败。需要分类器或小模型估复杂度：简单事实直答，需要证据则检索，需要组合则多跳。分类错误的代价不对称——漏检索通常比多余检索更伤事实任务，阈值应偏召回。<span class="marginnote">术语先翻译：「单跳」就是检索一次拿到证据就作答，像查一个词直接翻词典；「多跳」是答案藏在链条里——先查&quot;A 的领导是谁&quot;，再查&quot;这位领导毕业于哪&quot;——要检索两三次、把中间结果接起来。题目越绕，跳数越多，延迟与出错点也随之翻倍。</span></p><p>与<a href="/llm/abstention-calibrated-refusal">弃权</a> 的关系：低校准自信时应检索或拒答，而不是硬编。自适应是决策，校准是输入特征之一。</p><p><span class="marginnote">用 LLM 自己说「我需要检索吗」会自我偏好式地乱。应用独立路由头或规则（含时间词、含内部文档名则检索）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>路由特征：问题类型、是否含私有实体、口头或模型自信、历史检索失败。动作：直答 / 单跳 / 多跳 / 澄清。用<a href="/llm/rag-evaluation">评测课</a>的分列指标做决策的奖励：多余检索惩罚延迟与忠实度下降。上线后用<a href="/llm/deployment-monitoring">部署监控</a>看路由漂移。<span class="marginnote">直觉类比：把整个系统想成一场开卷考试的路由员——送分题（&quot;水的沸点是多少&quot;）让考生直接写；要查资料的定义题翻一次书；要交叉核对的比较题翻好几轮。路由员的水平不在于会不会做题，而在于&quot;看一眼就知道这题该不该翻书&quot;。</span></p>',9)),(E(),r(n,null,{default:e(()=>[i(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%97%AE%E9%A2%98%22%5D%20--%3E%20RT%5B%22%E8%B7%AF%E7%94%B1%22%5D%0A%20%20RT%20--%3E%20A%5B%22%E7%9B%B4%E7%AD%94%22%5D%0A%20%20RT%20--%3E%20S%5B%22%E5%8D%95%E8%B7%B3%E6%A3%80%E7%B4%A2%22%5D%0A%20%20RT%20--%3E%20M%5B%22%E5%A4%9A%E8%B7%B3%22%5D%0A%20%20RT%20--%3E%20C%5B%22%E6%BE%84%E6%B8%85%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[t("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,"检索改变条件分布：加入块等于换上下文。路由是在估计「当前参数分布是否足够」。估计器若与阅读器同参数且未单独训，会把「我会说」当成「我知道」。分离路由头、用检索是否改变答案的反事实当监督，更接近决策质量。",-1)),(E(),r(n,null,{default:e(()=>[i(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20ERR%5B%22%E8%B7%AF%E7%94%B1%E5%88%A4%E9%94%99%E7%9A%84%E4%B8%A4%E7%A7%8D%E6%96%B9%E5%90%91%22%5D%20--%3E%20MISS%5B%22%E8%AF%A5%E6%A3%80%E6%9C%AA%E6%A3%80%EF%BC%9A%E6%97%A0%E8%AF%81%E6%8D%AE%E7%A1%AC%E7%BC%96%22%5D%0A%20%20ERR%20--%3E%20EXTRA%5B%22%E4%B8%8D%E8%AF%A5%E6%A3%80%E8%80%8C%E6%A3%80%EF%BC%9A%E5%BB%B6%E8%BF%9F%E7%A8%8E%E5%8A%A0%E5%99%AA%E5%A3%B0%22%5D%0A%20%20MISS%20--%3E%20BIG%5B%22%E4%BA%8B%E5%AE%9E%E9%97%AE%E7%AD%94%E4%BB%A3%E4%BB%B7%E5%A4%A7%EF%BC%8C%E7%9B%B4%E6%8E%A5%E9%94%99%22%5D%0A%20%20EXTRA%20--%3E%20SMALL%5B%22%E4%BB%A3%E4%BB%B7%E8%BE%83%E5%B0%8F%EF%BC%9A%E6%85%A2%E4%B8%80%E7%82%B9%E3%80%81%E7%95%A5%E8%A2%AB%E6%B1%A1%E6%9F%93%22%5D%0A%20%20BIG%20--%3E%20THR%5B%22%E9%98%88%E5%80%BC%E5%81%8F%E5%8F%AC%E5%9B%9E%EF%BC%9A%E5%AE%81%E5%8F%AF%E5%A4%9A%E6%A3%80%22%5D%0A%20%20SMALL%20--%3E%20THR%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">为什么重要：大模型最擅长的就是把错误答案说得同样流利，所以&quot;它答得顺不顺&quot;完全不能当路由信号——「我会说」和「我知道」是两回事。这就是为什么路由要用独立的小模型或规则，并用&quot;检索前后答案是否变化&quot;这类客观信号来训练，而不是问模型本人&quot;你需要查资料吗&quot;。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>自适应不是关闭索引的借口。下一课：决定检索之后，块仍可能超出窗口，需要压缩。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>检索是动作，不是常量；漏检索与多余检索代价不对称。</li><li>路由要独立监督与分列指标，不能只靠模型自述。</li><li>复杂度阶梯：直答 / 单跳 / 多跳。</li><li>出处：Jeong 等 Adaptive-RAG。</li></ul>',5))])}const g=s(p,[["render",m]]);export{T as __pageData,g as default};
